namespace Archy.Features.Health.CalculateDocumentationDebt;
/// <summary>Counts only nodes eligible and allowed for summaries; disabled AI never creates artificial documentation debt.</summary>
public sealed class DocumentationDebtCalculator(DocumentationDebtOptions options):IDocumentationDebtCalculator { public DocumentationDebtMetric Calculate(long graphRevision,IReadOnlyList<DocumentationDebtCandidate> candidates){ArgumentNullException.ThrowIfNull(candidates);if(graphRevision<1||options.StaleAfterRevisions<1||candidates.Any(c=>c is null||string.IsNullOrWhiteSpace(c.StableId)||c.LastSummaryRevision<0||c.LastSummaryRevision>graphRevision)||candidates.Select(c=>c.StableId).Distinct(StringComparer.Ordinal).Count()!=candidates.Count)throw new ArgumentException("Documentation debt requires unique valid revision candidates.",nameof(candidates));var eligible=candidates.Where(c=>c.IsEligible&&c.AiEnabled).ToArray();var stale=eligible.Where(c=>graphRevision-c.LastSummaryRevision>=options.StaleAfterRevisions).OrderBy(c=>c.StableId,StringComparer.Ordinal).ToArray();return new(graphRevision,eligible.Length,stale.Length,stale.Length==0?0:stale.Max(c=>graphRevision-c.LastSummaryRevision),[..stale.Select(c=>c.StableId)]);}}
